DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261013125610_AddPhaseAShipmentsAndDelivery') THEN

    INSERT INTO "Shipments" ("OrderId", "SellerId", "Status", "TrackingNumber", "DeliveryCost", "EtaMinDays", "EtaMaxDays", "CreatedAt")
    SELECT DISTINCT
        oi."OrderId",
        p."SellerId",
        CASE o."Status"
            WHEN 'Pending' THEN 'Created'
            WHEN 'Shipped' THEN 'InTransit'
            WHEN 'Delivered' THEN 'Delivered'
            WHEN 'Cancelled' THEN 'Cancelled'
            ELSE 'Created'
        END AS "Status",
        'BOSTA-LEGACY-' || oi."OrderId" || '-' || p."SellerId" AS "TrackingNumber",
        0.00 AS "DeliveryCost",
        2 AS "EtaMinDays",
        4 AS "EtaMaxDays",
        o."CreatedAt"
    FROM "OrderItems" oi
    INNER JOIN "Products" p ON p."Id" = oi."ProductId"
    INNER JOIN "Orders" o ON o."Id" = oi."OrderId";

    UPDATE "OrderItems" oi
    SET "ShipmentId" = s."Id"
    FROM "Products" p, "Shipments" s
    WHERE oi."ProductId" = p."Id"
      AND s."OrderId" = oi."OrderId"
      AND s."SellerId" = p."SellerId";

    END IF;
END $EF$;

