DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030011003_MakeOrderIdempotencyIndexUnique') THEN

    UPDATE "Orders" o
    SET "IdempotencyKey" = NULL
    WHERE o."IdempotencyKey" IS NOT NULL
      AND o."IdempotencyKey" <> ''
      AND EXISTS (
          SELECT 1 FROM "Orders" k
          WHERE k."BuyerId" = o."BuyerId"
            AND k."IdempotencyKey" = o."IdempotencyKey"
            AND k."Id" < o."Id");
    END IF;
END $EF$;

