    CREATE UNIQUE INDEX IF NOT EXISTS "IX_Orders_BuyerId_IdempotencyKey" ON "Orders" ("BuyerId", "IdempotencyKey") WHERE "IdempotencyKey" IS NOT NULL AND "IdempotencyKey" <> '';
